@section('content')<div><h1 class="text-3xl font-bold">Reports & Exports</h1><p class="mt-1 text-sm text-slate-500">Choose the report period, fields, and column order.</p></div><form method="GET" action="{{ route('reports.index') }}" class="mt-6 rounded-xl border bg-white p-6"><div class="grid gap-4 md:grid-cols-2"><div><label class="label">From</label><input class="input" type="date" name="from" value="{{ request('from',now()->startOfMonth()->toDateString()) }}"></div><div><label class="label">To</label><input class="input" type="date" name="to" value="{{ request('to',now()->endOfMonth()->toDateString()) }}"></div></div><h2 class="mt-7 font-semibold">Columns</h2><p class="mt-1 text-sm text-slate-500">Select the fields you need, then drag the selected fields to reorder them.</p><div class="mt-4 grid gap-6 md:grid-cols-2"><div class="rounded-lg border p-4">@foreach($columns as $key=>$label)<label class="flex items-center gap-2 py-1.5"><input class="column-toggle" type="checkbox" name="columns[]" value="{{ $key }}" @checked(in_array($key,$selected,true))>{{ $label }}</label>@endforeach</div><div id="orderList" class="min-h-40 rounded-lg border p-4">@foreach($order as $key)<div draggable="true" data-key="{{ $key }}" class="mb-2 cursor-move rounded bg-slate-100 px-3 py-2">{{ $columns[$key] }}</div>@endforeach</div></div><input type="hidden" name="order_json" id="order_json"><div class="mt-6 flex gap-3"><button class="btn">Apply selection</button><a class="btn-secondary" href="{{ route('reports.index') }}">Reset</a></div></form><div class="mt-6 grid gap-4 md:grid-cols-3">@foreach(['xlsx'=>'Export Excel (.xlsx)','csv'=>'Export CSV','pdf'=>'Export PDF'] as $fmt=>$label)<form method="GET" action="{{ route('reports.export',$fmt) }}" class="rounded-xl border bg-white p-5"><input type="hidden" name="from" value="{{ request('from',now()->startOfMonth()->toDateString()) }}"><input type="hidden" name="to" value="{{ request('to',now()->endOfMonth()->toDateString()) }}"><input type="hidden" name="columns" value="{{ implode(',',$selected) }}"><input type="hidden" name="order" value="{{ implode(',',$order) }}"><button class="font-semibold">{{ $label }}</button></form>@endforeach</div><form method="POST" action="{{ route('reports.preferences') }}" class="mt-6 rounded-xl border bg-white p-6">@csrf<input class="input" name="name" placeholder="Layout name e.g. Management report" required><div id="pref-hidden"></div><label class="mt-3 flex items-center gap-2 text-sm"><input type="checkbox" name="is_default" value="1"> Make default layout</label><button class="btn mt-4">Save layout</button></form><script>(function(){const list=document.getElementById('orderList');let drag=null;function sync(){const keys=[...list.querySelectorAll('[data-key]')].map(x=>x.dataset.key);document.getElementById('order_json').value=JSON.stringify(keys);document.getElementById('pref-hidden').innerHTML=keys.map(k=>`<input type="hidden" name="columns[]" value="${k}"><input type="hidden" name="order[]" value="${k}">`).join('');}list.addEventListener('dragstart',e=>drag=e.target.closest('[data-key]'));list.addEventListener('dragover',e=>e.preventDefault());list.addEventListener('drop',e=>{e.preventDefault();const t=e.target.closest('[data-key]');if(drag&&t&&drag!==t)t.before(drag);sync()});document.querySelectorAll('.column-toggle').forEach(t=>t.addEventListener('change',()=>{const current=list.querySelector(`[data-key="${t.value}"]`);if(t.checked&&!current){const d=document.createElement('div');d.draggable=true;d.dataset.key=t.value;d.className='mb-2 cursor-move rounded bg-slate-100 px-3 py-2';d.textContent=t.parentElement.innerText.trim();list.appendChild(d)}else if(!t.checked&&current)current.remove();sync()}));sync();})();</script>@endsection
